43:     private Accepted resolveSnapshot(WorkstreamPaths paths) throws IOException {
44:         var occurrence = lastAcceptanceOccurrence(paths);
45:         var node = ledger.loadNode(paths, occurrence.nodeInstanceId());
46:         if (!"gate.human_acceptance".equals(node.nodeDefinitionId()) || node.status() != NodeStatus.COMPLETED) {
47:             throw new IOException("final acceptance node is not completed");
48:         }
49:         var gatePath = paths.gateJson(occurrence.gateId());
50:         if (!Files.isRegularFile(gatePath)) throw new IOException("final acceptance gate document is missing");
51:         var gate = objectMapper.readValue(gatePath.toFile(), GateDocument.class);
52:         if (!gate.nodeInstanceId().equals(node.nodeInstanceId()) || !"resolved".equals(gate.status())) {
53:             throw new IOException("final acceptance gate lineage or status is invalid");
54:         }
55:         var action = text(gate.result().get("human_action"));
56:         if (!"approve".equals(action) && !"approved".equals(action)) {
57:             throw new IOException("final acceptance occurrence was not approved: " + action);
58:         }
59:         var gateRefs = textList(gate.result().get("subject_input_refs"));
60:         if (!gateRefs.equals(node.inputRefs())) {
61:             throw new IOException("final acceptance gate subject refs do not match node input refs");
62:         }
63:         var candidateRefs = gateRefs.stream().filter(AcceptedDeliveryCandidateResolver::candidateRef).toList();
64:         if (candidateRefs.isEmpty()) {
65:             throw new MissingBindingException("final acceptance gate does not bind a delivery candidate");
66:         }
67:         if (candidateRefs.size() != 1) {
68:             throw new IOException("final acceptance gate must bind exactly one delivery candidate");
69:         }
70:         var candidateRef = candidateRefs.get(0);
71:         var candidatePath = resolveInsideWorkspace(paths, candidateRef);
72:         var occurrenceDir = candidatePath.getParent();
73:         if (occurrenceDir == null) throw new IOException("delivery candidate occurrence directory is missing");
74:         var published = candidateWriter.existing(paths, occurrenceDir.getFileName().toString());
75:         if (published == null || !published.path().toAbsolutePath().normalize().equals(candidatePath)) {
76:             throw new IOException("final acceptance candidate ref does not identify the published candidate");
77:         }
78:         var candidate = published.document();
79:         if (!candidate.workstreamId().equals(paths.workstreamId().value())
80:                 || !candidate.iterationId().equals(node.iterationId())) {
81:             throw new IOException("delivery candidate workstream or iteration lineage does not match acceptance");
82:         }
83:         var producer = ledger.loadNode(paths, candidate.producerNodeInstanceId());
84:         if (!"delivery.prepare_pr".equals(producer.nodeDefinitionId())
85:                 || producer.status() != NodeStatus.COMPLETED
86:                 || !producer.iterationId().equals(candidate.iterationId())
87:                 || !producer.outputRefs().contains(candidateRef)) {
88:             throw new IOException("delivery candidate producer lineage is invalid");
89:         }
90:         return new Accepted(candidateRef, published.sha256(), candidate, gate, node, producer);
