93:     private Occurrence lastAcceptanceOccurrence(WorkstreamPaths paths) throws IOException {
94:         if (!Files.isRegularFile(paths.eventsJsonl())) throw new IOException("workflow event history is missing");
95:         var occurrences = new ArrayList<Occurrence>();
96:         long previousWorkflowSequence = -1;
97:         for (var line : Files.readAllLines(paths.eventsJsonl(), StandardCharsets.UTF_8)) {
98:             if (line.isBlank()) continue;
99:             Map<String, Object> event;
100:             try {
101:                 event = objectMapper.readValue(line, MAP_TYPE);
102:             } catch (Exception failure) {
103:                 throw new IOException("workflow event history contains invalid JSON", failure);
104:             }
105:             var eventId = text(event.get("event_id"));
106:             var workflowEvent = WORKFLOW_EVENT_ID.matcher(eventId);
107:             if (!workflowEvent.matches()) {
108:                 if ("node_routed".equals(text(event.get("event_type")))) {
109:                     throw new IOException("routing event does not have a workflow event id");
110:                 }
111:                 continue;
112:             }
113:             var workflowSequence = Long.parseLong(workflowEvent.group(1));
114:             if (workflowSequence <= previousWorkflowSequence) {
115:                 throw new IOException("workflow event history is not strictly ordered");
116:             }
117:             previousWorkflowSequence = workflowSequence;
118:             if (!"node_routed".equals(text(event.get("event_type")))) continue;
119:             var payload = map(event.get("payload"));
120:             if (!"gate.human_acceptance".equals(text(payload.get("to")))) continue;
121:             var gateId = text(payload.get("gate_id"));
122:             var nodeInstanceId = text(payload.get("node_instance_id"));
123:             if (gateId.isBlank() || nodeInstanceId.isBlank()) {
124:                 throw new IOException("acceptance routing event is missing gate lineage");
125:             }
126:             occurrences.add(new Occurrence(eventId, gateId, nodeInstanceId));
127:         }
128:         if (occurrences.isEmpty()) throw new MissingBindingException("final acceptance occurrence is missing");
129:         return occurrences.get(occurrences.size() - 1);
130:     }
