162:     /** Returning from this method proves this live invocation completed its local commit only. */
163:     public void commit() throws IOException {
164:         requireWritable();
165:         if (replacements.isEmpty() && appends.isEmpty()) { committed = true; return; }
166:         // Every mutation, including a claim with no domain event, advances the same current read identity.
167:         var current = readTree(paths.workflowCurrentJson());
168:         if (!(current instanceof com.fasterxml.jackson.databind.node.ObjectNode object)) throw invalid("missing current document");
169:         object.put("commitSequence", Math.addExact(baseSequence(), 1));
170:         write(paths.workflowCurrentJson(), object);
171:         var targets = new ArrayList<Target>();
172:         for (var entry : replacements.entrySet()) {
173:             targets.add(new Target(relative(entry.getKey()), sha(originals.get(entry.getKey())),
174:                     entry.getValue(), sha(entry.getValue())));
175:         }
176:         var tails = new ArrayList<Append>();
177:         for (var entry : appends.entrySet()) {
178:             var before = originals.get(entry.getKey());
179:             tails.add(new Append(relative(entry.getKey()), before == null ? 0 : before.length, sha(concat(before, null)),
180:                     entry.getValue(), sha(concat(before, entry.getValue()))));
181:         }
182:         if (targets.isEmpty() && tails.isEmpty()) { committed = true; return; }
183:         var id = UUID.randomUUID().toString();
184:         var mutation = new Mutation(1, id, paths.workstreamId().value(), runtimeIdentity,
185:                 operation, requestId, baseSequence(), List.copyOf(targets), List.copyOf(tails));
186:         var pending = root.resolve("pending").resolve(id + ".json");
187:         validateMutation(pending, mutation);
188:         // Detect changes made outside this session before making the plan authoritative.
189:         validateStates(mutation);
190:         faultPoint.at("before_manifest", pending);
191:         writer.write(pending, mutation);
192:         faultPoint.at("after_manifest", pending);
193:         apply(pending, mutation);
194:         committed = true;
195:     }

