30:     public static Map<String, Object> describe(WorkflowFileLedger ledger, WorkstreamPaths paths) throws IOException {
31:         return ledger.inspect(paths, (scoped, files) -> {
32:             var current = scoped.loadCurrent(paths);
33:             if (current.activeNodeInstanceIds().size() != 1) return Map.of();
34:             var node = scoped.loadNode(paths, current.activeNodeInstanceIds().getFirst());
35:             if (!"UNKNOWN".equals(node.result().get("external_effect"))) return Map.of();
36:             var execution = scoped.latestNodeExecution(paths, node).orElseThrow(() -> new IOException("unknown effect without execution"));
37:             var prepared = AgentRunCommitProtocol.boundPreparation(paths, execution);
38:             var binding = JSON.readTree(prepared.path().toFile()).path("binding");
39:             var contract = originalContract(scoped, paths, node, binding);
40:             var request = new Request("dual.execution-recovery.v1", "", paths.workstreamId().value(), node.nodeInstanceId(),
41:                     execution.agentTaskId(), execution.nodeExecutionId(), binding.path("run").path("runId").asText(),
42:                     ledger.frozenRuntimeIdentity(), contract == null ? 0 : contract.epoch(), current.lastEventId(), hash(files.readBytes(paths.nodeJson(node.nodeInstanceId()))),
43:                     new TaskContract.Reference(prepared.reference().get("ref"), prepared.reference().get("sha256")), "", List.of(), false, "");
44:             return Map.of("decision_template", request, "executor_owns_invocation", AgentRunCommitProtocol.executorOwnsInvocation(paths, execution),
45:                     "external_effect", "UNKNOWN", "risk", "A new attempt can repeat effects; a successful stop does not prove they never happened.");
46:         });
47:     }
