49:     public static void apply(WorkflowFileLedger ledger, WorkstreamPaths paths, Request request) throws IOException {
50:         require(request != null && "dual.execution-recovery.v1".equals(request.schema())
51:                 && request.requestId() != null && request.requestId().matches("[A-Za-z0-9._-]{1,80}")
52:                 && request.execution() != null && request.execution().matches("[A-Za-z0-9_-]{1,100}")
53:                 && Set.of("AUTHORIZE_NEW_ATTEMPT", "ABORT", "ADOPT_VERIFIED_RESULT").contains(request.disposition())
54:                 && request.operatorNote() != null && !request.operatorNote().isBlank(), "invalid recovery decision");
55:         require(paths.workstreamId().value().equals(request.workstream())
56:                 && ledger.frozenRuntimeIdentity().equals(request.frozenIdentity()), "wrong workstream or frozen identity");
57:         var requestJson = JSON.readTree(JSON.writeValueAsBytes(request));
58:         try (var write = ledger.writeSession(paths, "adjudicate unknown execution", request.requestId())) {
59:             var scoped = write.ledger();
60:             var execution = write.files().read(paths.nodeExecutionJson(request.execution()), NodeExecutionDocument.class);
61:             var previous = JSON.valueToTree(execution.result()).path("recovery_decisions").path(request.requestId());
62:             if (!previous.isMissingNode()) {
63:                 require(previous.path("request").equals(requestJson), "request id was used with different content");
64:                 return;
65:             }
66:             var current = scoped.loadCurrent(paths);
67:             require(current.lastEventId().equals(request.lastEvent())
68:                     && current.activeNodeInstanceIds().equals(List.of(request.node())), "recovery observation is stale");
69:             var node = scoped.loadNode(paths, request.node());
70:             require(execution.nodeInstanceId().equals(node.nodeInstanceId()) && execution.agentTaskId().equals(request.task())
71:                     && node.latestExecutionId().equals(execution.nodeExecutionId())
72:                     && hash(write.files().readBytes(paths.nodeJson(node.nodeInstanceId()))).equals(request.nodeSha256()),
73:                     "node, task or execution identity changed");
74:             var prepared = AgentRunCommitProtocol.boundPreparation(paths, execution);
75:             require(request.prepared() != null && prepared.reference().get("ref").equals(request.prepared().ref())
76:                     && prepared.reference().get("sha256").equals(request.prepared().sha256()), "prepared reference mismatch");
77:             var input = JSON.readTree(prepared.path().toFile());
78:             var binding = input.path("binding");
79:             require(binding.path("run").path("runId").asText().equals(request.attempt()), "attempt mismatch");
80:             require(!AgentRunCommitProtocol.executorOwnsInvocation(paths, execution), "original executor is still active");

