61:     private static String nextAction(DeliveryApplicationService.View view) {
62:         if ("WORKFLOW_NOT_DELIVERABLE".equals(view.reasonCode())) {
63:             return "The workflow is not yet eligible for delivery.";
64:         }
65:         return switch (view.status()) {
66:             case "READY" -> "Apply the accepted candidate to the original repository.";
67:             case "APPLIED" -> "Review and commit the staged target diff, then finalize that commit.";
68:             case "FAILED", "BLOCKED" -> "Resolve the recorded boundary failure before retrying delivery.";
69:             case "COMMITTED" -> "The accepted delivery candidate has been committed.";
70:             default -> "Refresh the delivery view.";
71:         };
72:     }
73: 
74:     private static String operatorNextAction(DeliveryApplicationService.View view) {
75:         if ("WORKFLOW_NOT_DELIVERABLE".equals(view.reasonCode())) {
76:             return "当前尚不可交付；请先完成工作流与完成审计。";
77:         }
78:         return switch (view.status()) {
79:             case "READY" -> "候选内容已与人工验收绑定，可以合回原始仓库。";
80:             case "APPLIED" -> "改动已暂存。检查后手工提交，再登记提交 SHA 完成交付。";
81:             case "FAILED", "BLOCKED" -> "先处理已记录的边界错误，再重试交付。";
82:             case "COMMITTED" -> "已验证提交内容与获批候选完全一致。";
83:             default -> "刷新交付视图。";
84:         };
85:     }
