87:     private static List<String> nextCommands(DeliveryApplicationService.View view, String workstreamId) {
88:         if (view.targetRepo().isBlank()) return List.of();
89:         var cd = "cd " + shellQuote(view.targetRepo());
90:         if (view.canMerge()) {
91:             return List.of(cd, "git status", "git diff --stat");
92:         }
93:         if (view.canFinalize()) {
94:             return List.of(
95:                     cd,
96:                     "git diff --cached",
97:                     "git commit -m " + shellQuote("feat: dual delivery " + workstreamId),
98:                     "dualctl delivery finalize --commit $(git rev-parse HEAD) --workdir <source-worktree> " + workstreamId
99:             );
100:         }
101:         return "COMMITTED".equals(view.status())
102:                 ? List.of(cd, "git show --stat " + view.commit())
103:                 : List.of();

